function namespaceSvgIds(markup: string, prefix: string): string {
  const idRegex = /\bid="([^"]+)"/g;
  const idMap = new Map<string, string>();
  let next = 0;
  const withNamespacedIds = markup.replace(idRegex, (_match, id: string) => {
    const namespaced = `${prefix}-${id}-${next++}`;
    idMap.set(id, namespaced);
    return `id="${namespaced}"`;
  });

  let result = withNamespacedIds;
  idMap.forEach((newId, oldId) => {
    result = result.replaceAll(`url(#${oldId})`, `url(#${newId})`);
    result = result.replaceAll(`="#${oldId}"`, `="#${newId}"`);
  });
  return result;
}

function ToolbarIcon({ markup }: { markup: string }) {
  const iconId = useId().replaceAll(":", "-");
  const safeMarkup = useMemo(() => namespaceSvgIds(markup, `toolbar-svg-${iconId}`), [iconId, markup]);
  return <span aria-hidden style={{ width: 48, height: 48, display: "block" }} dangerouslySetInnerHTML={{ __html: safeMarkup }} />;
}

function IconScanColor() {
  return <ToolbarIcon markup={MONOCHROME_SVG} />;
}

function IconReviewTool() {
  return <ToolbarIcon markup={IOC_SVG} />;
}

function IconOcclusgram() {
  return <ToolbarIcon markup={OCC_SVG} />;
}

function IconMarginLine() {
  return <ToolbarIcon markup={MARGIN_LINE_SVG} />;
}

function IconTrim() {
  return <ToolbarIcon markup={TRIM_SVG} />;
}

function ChevronIcon({ up }: { up: boolean }) {
  const innerTransform = up
    ? undefined
    : "translate(30.5 26.5) scale(1 -1) translate(-30.5 -26.5)";

  return (
    <svg width="60" height="60" viewBox="0 0 61 60" fill="none" xmlns="http://www.w3.org/2000/svg">
      <path d="M0.5 60L0.499997 0L60.5 0L60.5 60L0.5 60Z" fill="white" />
      <path d="M0.5 60L1 60L0.999997 0L0.5 0L0 0L0 60L0.5 60Z" fill="#F0F0F0" />
      <rect
        x="18.5"
        y="18"
        width="24"
        height="24"
        rx="3"
        stroke="#3E3D40"
        strokeWidth="2"
        fill="none"
      />
      <line
        x1="18.5"
        y1="35"
        x2="42.5"
        y2="35"
        stroke="#3E3D40"
        strokeWidth="2"
        strokeLinecap="round"
      />
      <path
        d="M25.5 24L30.5 29L35.5 24"
        stroke="#3E3D40"
        strokeWidth="2"
        strokeLinecap="round"
        strokeLinejoin="round"
        fill="none"
        transform={innerTransform}
      />
    </svg>
  );
}

const VIEW_TOOLS: { id: ViewToolId; label: string; Icon: () => React.JSX.Element }[] = [
  { id: "scan-color", label: "Color", Icon: IconScanColor },
  { id: "review-tool", label: "Review tool", Icon: IconReviewTool },
  { id: "occlusgram", label: "Occlusgram", Icon: IconOcclusgram },
  { id: "margin-line", label: "Margin line", Icon: IconMarginLine },
  { id: "trim", label: "Trim", Icon: IconTrim },
];

export default function ViewToolbar26A({
  className,
  expanded: controlledExpanded,
  onExpandedChange,
  onToolClick,
  activeTools: controlledActiveTools,
  onActiveToolsChange,
  showPrepQcAndMarginLineTools = true,
  mutuallyExclusiveToolPairs,
}: ViewToolbarProps) {
  const [internalExpanded, setInternalExpanded] = useState(true);
  const expanded = controlledExpanded ?? internalExpanded;
  const [internalActiveTools, setInternalActiveTools] = useState<Set<ViewToolId>>(new Set());
  const activeTools = controlledActiveTools ?? internalActiveTools;
  const setActiveTools = onActiveToolsChange ?? setInternalActiveTools;

  const visibleViewTools = useMemo(
    () =>
      showPrepQcAndMarginLineTools
        ? VIEW_TOOLS
        : VIEW_TOOLS.filter((t) => t.id !== "prep-qc" && t.id !== "margin-line"),
    [showPrepQcAndMarginLineTools],
  );

  function toggleExpanded() {
    const next = !expanded;
    onExpandedChange?.(next);
    setInternalExpanded(next);
  }

  return (
    <div
      className={`flex ${className ?? ""}`.trim()}
      style={{
        padding: 8,
        borderRadius: 8,
        backgroundColor: "#ffffff",
        boxShadow: "0px 4px 12px rgba(0,0,0,0.08)",
      }}
    >
      <div className="flex items-stretch justify-center" style={{ gap: 8 }}>
        <div className="flex items-start" style={{ gap: 12 }}>
          {visibleViewTools.map((tool) => {
            const isActive = activeTools.has(tool.id);
            return (
              <button
                key={tool.id}
                type="button"
                onClick={() => {
                  const next = new Set<ViewToolId>(activeTools);
                  if (next.has(tool.id)) {
                    next.delete(tool.id);
                  } else {
                    next.add(tool.id);
                    for (const [a, b] of mutuallyExclusiveToolPairs ?? []) {
                      if (tool.id === a) next.delete(b);
                      else if (tool.id === b) next.delete(a);
                    }
                  }
                  setActiveTools(next);
                  onToolClick?.(tool.id, next.has(tool.id));
                }}
                className="flex flex-col items-center justify-center cursor-pointer border-0 appearance-none outline-none transition-ui focus-visible:ring-2 focus-visible:ring-[var(--color-border-focus)] focus-visible:ring-offset-2"
                style={{
                  width: expanded ? 96.67 : 60,
                  height: expanded ? 90 : 60,
                  padding: 0,
                  gap: expanded ? 4 : 0,
                  backgroundColor: "transparent",
                }}
                aria-label={tool.label}
                aria-pressed={isActive}
              >
                <span
                  style={{
                    width: 60,
                    height: 60,
                    borderRadius: 8,
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "center",
                    backgroundColor: isActive ? "#A6E2F9" : "white",
                  }}
                >
                  <tool.Icon />
                </span>
                {expanded && (
                  <span
                    className="tp-body-01 font-medium"
                    style={{
                      color: isActive ? "#009ACE" : "var(--color-text-primary)",
                      whiteSpace: "nowrap",
                    }}
                  >
                    {tool.label}
                  </span>
                )}
              </button>
            );
          })}
        </div>

        <button
          type="button"
          onClick={toggleExpanded}
          className="flex items-center justify-center cursor-pointer border-0 appearance-none outline-none transition-ui focus-visible:ring-2 focus-visible:ring-[var(--color-border-focus)] focus-visible:ring-offset-2"
          style={{
            width: 60,
            backgroundColor: "white",
            padding: 0,
            flexShrink: 0,
          }}
          aria-label={expanded ? "Collapse toolbar" : "Expand toolbar"}
          aria-expanded={expanded}
        >
          <ChevronIcon up={expanded} />
        </button>
      </div>
    </div>
  );
}
